from urllib.parse import parse_qsl


def parse_request_body(body, allow_blank=True):
    """Pre-fix logic, getsentry/responses matchers.py @ 8afa534~1"""
    return dict(parse_qsl(body, keep_blank_values=allow_blank)) if body else {}

tests.test_mod.py:
from mod import parse_request_body


def test_str_body():
    assert parse_request_body("a=1&b=2") == {"a": "1", "b": "2"}


def test_bytes_body_no_crash():
    assert parse_request_body(b"a=1&b=2") == {"a": "1", "b": "2"}


def test_blank_allowed():
    assert parse_request_body(b"a=&b=2")["a"] == ""
